import { HevyHttpError } from "@hevy-mcp/hevy-client";
import { describe, expect, it } from "vitest";
import {
	classifyReadError,
	isExpectedReadEndOfList,
	isExpectedReadNotFound,
} from "./operation-errors.js";

function notFound(endpoint: string, method = "GET") {
	return new HevyHttpError("not found", {
		status: 404,
		method,
		endpoint,
	});
}

describe("classifyReadError", () => {
	it("classifies a known resource 404", () => {
		const error = notFound("/v1/routines/routine-1");

		expect(classifyReadError(error, "/v1/routines")).toBe("not_found");
		expect(isExpectedReadNotFound(error, "/v1/routines")).toBe(true);
	});

	it("classifies a later collection-page 404", () => {
		const error = notFound("/v1/workouts");

		expect(classifyReadError(error, "/v1/workouts", 2)).toBe("end_of_list");
		expect(isExpectedReadEndOfList(error, "/v1/workouts", 2)).toBe(true);
	});

	it("does not hide first-page, mutation, or unrelated 404s", () => {
		expect(
			classifyReadError(notFound("/v1/workouts"), "/v1/workouts", 1),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/workouts", "POST"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/routines/routine-1"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(new Error("network failure"), "/v1/workouts", 2),
		).toBeUndefined();
	});
});

import { Schema } from "effect";

const executionFields = {
	phase: Schema.optional(
		Schema.Union([
			Schema.Literal("before-dispatch"),
			Schema.Literal("dispatch"),
			Schema.Literal("response-headers"),
			Schema.Literal("response-content"),
			Schema.Literal("backoff"),
			Schema.Literal("completed"),
		]),
	),
	operationSafety: Schema.optional(
		Schema.Union([
			Schema.Literal("read"),
			Schema.Literal("idempotent-write"),
			Schema.Literal("non-idempotent-write"),
		]),
	),
	commitState: Schema.optional(
		Schema.Union([
			Schema.Literal("not_sent"),
			Schema.Literal("confirmed"),
			Schema.Literal("unknown"),
		]),
	),
	safeToRetry: Schema.optional(Schema.Boolean),
	outcome: Schema.optional(
		Schema.Union([
			Schema.Literal("success"),
			Schema.Literal("expected"),
			Schema.Literal("retryable_failure"),
			Schema.Literal("terminal_failure"),
			Schema.Literal("cancelled"),
			Schema.Literal("deadline_exceeded"),
		]),
	),
} as const;

/** Typed error vocabulary for Effect-based client integrations. */
export class RateLimitError extends Schema.TaggedError<RateLimitError>()(
	"RateLimitError",
	{
		status: Schema.Number,
		endpoint: Schema.String,
		method: Schema.String,
		retryAfterSeconds: Schema.optional(Schema.Number),
		retryCount: Schema.optional(Schema.Number),
		retryExhausted: Schema.optional(Schema.Boolean),
		...executionFields,
	},
) {}

export class ValidationError extends Schema.TaggedError<ValidationError>()(
	"ValidationError",
	{
		status: Schema.Number,
		endpoint: Schema.String,
		method: Schema.String,
		...executionFields,
	},
) {}

export class NotFoundError extends Schema.TaggedError<NotFoundError>()(
	"NotFoundError",
	{
		status: Schema.Number,
		endpoint: Schema.String,
		method: Schema.String,
		expected: Schema.Boolean,
		...executionFields,
	},
) {}

export class NetworkError extends Schema.TaggedError<NetworkError>()(
	"NetworkError",
	{
		code: Schema.String,
		...executionFields,
		retryCount: Schema.optional(Schema.Number),
		retryExhausted: Schema.Boolean,
	},
) {}

export class ApiError extends Schema.TaggedError<ApiError>()("ApiError", {
	status: Schema.Number,
	endpoint: Schema.String,
	method: Schema.String,
	...executionFields,
}) {}

